package cmd

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/AlecAivazis/survey/v2"
	"github.com/fatih/color"
	"github.com/spf13/cobra"
)

var (
	applyNamespace string
	applyDryRun    bool
)

// applyCmd wraps kubectl apply for manifests generated by nova
var applyCmd = &cobra.Command{
	Use:   "apply [path]",
	Short: "Apply Kubernetes manifests using kubectl",
	Long: `apply runs 'kubectl apply' on the specified directory or file. Defaults to
./k8s/ if no path is given. Supports namespace override and dry-run mode.

Examples:
  nova cluster apply                     — applies all manifests in ./k8s/
  nova cluster apply ./k8s/my-app/       — applies manifests in a specific app directory
  nova cluster apply -n staging          — applies to the 'staging' namespace
  nova cluster apply --dry-run           — validates manifests without applying`,
	Run: runApply,
}

func runApply(cmd *cobra.Command, args []string) {
	green := color.New(color.FgGreen)
	red := color.New(color.FgRed)
	cyan := color.New(color.FgCyan)

	// Check kubectl is available
	if _, err := exec.LookPath("kubectl"); err != nil {
		red.Println("Error: 'kubectl' not found in PATH.")
		fmt.Println("Install kubectl: https://kubernetes.io/docs/tasks/tools/")
		os.Exit(1)
	}

	target := "./k8s/"
	if len(args) > 0 {
		target = args[0]
	}

	// Check target exists
	info, err := os.Stat(target)
	if err != nil {
		red.Printf("Error: path '%s' does not exist\n", target)
		os.Exit(1)
	}

	kubectlArgs := []string{"apply"}

	if info.IsDir() {
		kubectlArgs = append(kubectlArgs, "-f", target, "--recursive")
	} else {
		kubectlArgs = append(kubectlArgs, "-f", target)
	}

	if applyNamespace != "" {
		kubectlArgs = append(kubectlArgs, "-n", applyNamespace)
	}

	if applyDryRun {
		kubectlArgs = append(kubectlArgs, "--dry-run=client")
	}

	cyan.Printf("Running: kubectl %s\n\n", strings.Join(kubectlArgs, " "))

	kubectlCmd := exec.Command("kubectl", kubectlArgs...)
	kubectlCmd.Stdout = os.Stdout
	kubectlCmd.Stderr = os.Stderr

	if err := kubectlCmd.Run(); err != nil {
		red.Printf("\nError: kubectl apply failed: %v\n", err)
		os.Exit(1)
	}

	if applyDryRun {
		green.Println("\n✓ Dry-run completed successfully (no resources were modified)")
	} else {
		green.Println("\n✓ Manifests applied successfully")
	}
}

// deleteK8sCmd wraps kubectl delete
var deleteK8sCmd = &cobra.Command{
	Use:   "delete [path]",
	Short: "Delete Kubernetes resources from manifest files",
	Long: `delete runs 'kubectl delete' on the specified directory or file. Defaults to
./k8s/ if no path is given.

Examples:
  nova cluster delete                    — deletes all resources defined in ./k8s/
  nova cluster delete ./k8s/my-app/      — deletes resources from a specific app directory`,
	Run: func(cmd *cobra.Command, args []string) {
		red := color.New(color.FgRed)
		cyan := color.New(color.FgCyan)
		green := color.New(color.FgGreen)

		if _, err := exec.LookPath("kubectl"); err != nil {
			red.Println("Error: 'kubectl' not found in PATH.")
			os.Exit(1)
		}

		target := "./k8s/"
		if len(args) > 0 {
			target = args[0]
		}

		if _, err := os.Stat(target); err != nil {
			red.Printf("Error: path '%s' does not exist\n", target)
			os.Exit(1)
		}

		var confirm bool
		survey.AskOne(&survey.Confirm{
			Message: fmt.Sprintf("Delete all resources defined in '%s'?", target),
			Default: false,
		}, &confirm)

		if !confirm {
			fmt.Println("Aborted.")
			return
		}

		kubectlArgs := []string{"delete", "-f", target, "--recursive"}
		if applyNamespace != "" {
			kubectlArgs = append(kubectlArgs, "-n", applyNamespace)
		}

		cyan.Printf("Running: kubectl %s\n\n", strings.Join(kubectlArgs, " "))

		kubectlCmd := exec.Command("kubectl", kubectlArgs...)
		kubectlCmd.Stdout = os.Stdout
		kubectlCmd.Stderr = os.Stderr

		if err := kubectlCmd.Run(); err != nil {
			red.Printf("\nError: kubectl delete failed: %v\n", err)
			os.Exit(1)
		}

		green.Println("\n✓ Resources deleted successfully")
	},
}

func init() {
	applyCmd.Flags().StringVarP(&applyNamespace, "namespace", "n", "", "Override namespace for all resources")
	applyCmd.Flags().BoolVar(&applyDryRun, "dry-run", false, "Validate manifests without applying (client-side dry-run)")

	deleteK8sCmd.Flags().StringVarP(&applyNamespace, "namespace", "n", "", "Override namespace for all resources")

	clusterCmd.AddCommand(applyCmd)
	clusterCmd.AddCommand(deleteK8sCmd)
}
